'use strict';
/* Fast Pro WR search: exact current portfolio engine is patched in-memory. BUY+SELL are always evaluated together. */
const fs=require('fs'),vm=require('vm');
const SRC='scripts/live-portfolio-backtest-20260915.js';
if(!fs.existsSync(SRC)){console.error('Missing '+SRC);process.exit(1)}
const original=fs.readFileSync(SRC,'utf8');
const anchor="function signalPro(i){";
const endAnchor="function signalRange(i){";
if(!original.includes(anchor)||!original.includes(endAnchor)){console.error('PRO anchors missing');process.exit(2)}
function extractMetrics(logs){const line=logs.find(x=>/^PRO\s+T\d+/.test(x));if(!line)return null;const m=line.match(/T(\d+)\s+WR([\d.]+)%\s+PF([\d.∞]+)\s+NET([+-]?[\d.]+)R\s+DD([\d.]+)R\s+LS(\d+)/);if(!m)return null;return{n:+m[1],wr:+m[2],pf:m[3]==='∞'?999:+m[3],net:+m[4],dd:+m[5],ls:+m[6]}}
function run(q){let s=original;const a=s.indexOf(anchor),b=s.indexOf(endAnchor,a);const fn=`function signalPro(i){const d=dIdx[i];if(i<80||d<49||![R[i-1],R[i],X[i],A[i],DE50[d]].every(Number.isFinite))return;const now=M[i].t,dy=day(now);if(pro.lossDay!==dy){pro.lossDay=dy;pro.losses=0}if(pro.losses>=2||now<pro.cool)return;const dt=new Date(now),min=dt.getUTCHours()*60+dt.getUTCMinutes();if(dt.getUTCDay()===3&&min>=1020&&min<=1230)return;const bias=DC[d]>DE50[d]?'BUY':'SELL',aa=atrAvg(i),ratio=A[i]/aa;if(!Number.isFinite(ratio))return;let side=null;if(R[i-1]>=41&&R[i]<41&&bias==='BUY'&&X[i]>=${q.ba}&&ratio<=${q.br})side='BUY';if(R[i-1]<=63&&R[i]>63&&bias==='SELL'&&X[i]>=${q.sa}&&ratio<=${q.sr})side='SELL';if(!side)return;if(side==='BUY'&&[${q.bh.join(',')}].includes(hour(now)))return;if(side==='SELL'&&[${q.sh.join(',')}].includes(hour(now)))return;const z=M[i],rg=z.h-z.l;if(!(rg>0)||Math.abs(z.c-z.o)/rg<${q.body})return;if(side==='BUY'&&(i<36||z.c-M[i-36].c<${q.mom}))return;open('PRO',i,side,12,null,null)}\n`;
s=s.slice(0,a)+fn+s.slice(b);const logs=[];try{vm.runInNewContext(s,{require,console:{log:(...x)=>logs.push(x.join(' ')),error:(...x)=>logs.push(x.join(' '))},process,__dirname:__dirname,__filename:SRC,Buffer,setTimeout,clearTimeout},{filename:SRC,timeout:30000})}catch(e){if(q._debug)console.error('ENGINE ERROR:',e&&e.stack||e);return null}const z=extractMetrics(logs);if(!z&&q._debug){console.error('METRIC PARSE FAILED. Relevant output:');console.error(logs.filter(x=>/Pro Strategy|PRO|T\\d+ WR/.test(x)).join('\\n')||logs.slice(-30).join('\\n'))}return z}
const BASE={ba:27,br:1.30,sa:19,sr:1.15,mom:-20,body:.5,bh:[8],sh:[],_debug:true};const base=run(BASE);console.log('PRO — FAST COMBINED BUY+SELL WR SEARCH');console.log('BASE',base);if(!base||base.n!==239){console.log('⚠️ BASE parity differs from canonical T239; do not select live from this run.');process.exit(3)}
const out=[];for(const ba of [23,25,27,29])for(const br of [1.05,1.15,1.30])for(const sa of [17,19,21,23])for(const sr of [1.00,1.15,1.30])for(const mom of [-30,-20,-10,0])for(const body of [.45,.5,.6]){const q={ba,br,sa,sr,mom,body,bh:[8],sh:[]},m=run(q);if(m&&m.n>=150&&m.pf>=1.5&&m.dd<=6)out.push({q,m})}
out.sort((x,y)=>(y.m.wr-x.m.wr)||((y.m.pf-x.m.pf))||(y.m.net-x.m.net));console.log(`TESTED 1728 | RETAINED ${out.length}`);for(let i=0;i<Math.min(20,out.length);i++){const x=out[i];console.log(`#${i+1} BUY ADX${x.q.ba} ATR${x.q.br} MOM${x.q.mom} | SELL ADX${x.q.sa} ATR${x.q.sr} | BODY${x.q.body} => T${x.m.n} WR${x.m.wr.toFixed(1)} PF${x.m.pf.toFixed(2)} N${x.m.net>=0?'+':''}${x.m.net.toFixed(2)}R DD${x.m.dd.toFixed(2)} LS${x.m.ls}`)}
